using System;
using UnityEngine;
namespace LWS.TruckWallball.Editor {
public static class WallballFixtures {
 public static void Run(){int n=0;Action<bool,string> check=(v,s)=>{if(!v)throw new Exception("Wallball rule fixture: "+s);n++;};var r=new WallballRules();r.Start(0);check(r.Phase==WallballPhase.Countdown&&r.Score[0]==0,"opening countdown");check(!r.Strike(0),"countdown rejects hit");r.Tick(2);check(r.Phase==WallballPhase.Serving&&r.Eligible==0,"legal server eligibility");check(!r.Strike(1),"ineligible receiver rejected");check(r.Strike(0)&&r.Phase==WallballPhase.Outgoing&&r.Eligible==-1,"physical serve event launches outgoing");check(!r.Strike(0),"hitter cannot touch outgoing again");r.Wall(true);check(r.Phase==WallballPhase.Receiving&&r.Eligible==1&&r.Hitter==0,"valid wall transfers eligibility");r.Wall(true);check(r.LegalWalls==1,"sustained wall contact not a new return");check(r.Strike(1),"volley before floor bounce");r.Wall(true);r.Floor();check(r.Bounces==1&&r.Eligible==0,"one bounce retains return");check(r.Strike(0),"return after one bounce");r.Wall(true);r.Floor();r.Floor();check(r.Score[0]==1&&r.PointWinner==0&&r.Reason=="SECOND BOUNCE","second bounce faults receiver");r.Floor();r.Out();check(r.Points==1,"point resolved exactly once");r.Tick(2);r.Tick(2);check(r.Server==0&&r.Eligible==0,"rally winner serves");r.Strike(0);r.Floor();check(r.Score[1]==1&&r.Reason=="MISSED WALL","floor before wall faults hitter");
  r.Start(0);r.Tick(2);r.Strike(0);r.Wall(false);check(r.Score[1]==1&&r.Reason=="OUT","invalid wall target faults hitter");r.Start(1);r.Tick(2);r.Strike(1);r.Wall(true);r.Out();check(r.Score[0]==1&&r.PointWinner==0,"unreturned out is against hitter, not receiver");r.Start(0);r.Tick(2);r.Pause();float time=r.Timer;r.Tick(100);check(r.Timer==time&&r.Phase==WallballPhase.Paused,"pause preserves serve timeout");r.Resume();r.Tick(24);check(r.Score[0]+r.Score[1]==0,"generous visible serve window");r.Tick(1);check(r.Score[1]==1&&r.Reason=="SERVE TIMEOUT","serve timeout faults server");r.Start(0);r.Tick(2);r.Strike(0);r.Wall(true);r.Replay();check(r.Points==0&&r.Score[0]==0&&r.Server==0&&r.Phase==WallballPhase.Countdown,"neutral replay preserves score and original server");
  r.Start(0);r.Tick(2);for(int i=0;i<20;i++)Point(r,i%2);check(r.Score[0]==10&&r.Score[1]==10&&r.Winner<0,"10-10 deuce");Point(r,0);check(r.Score[0]==11&&r.Winner<0,"11-10 continues");Point(r,1);check(r.Score[1]==11&&r.Winner<0,"11-11 extended play");Point(r,0);check(r.Winner<0,"12-11 continues");Point(r,0);check(r.Winner==0&&r.Score[0]==13&&r.Score[1]==11,"win by two at 13-11");check(!r.Fault(0,"OUT")&&!r.Strike(0),"finished match locked");r.Start(1);r.Tick(2);check(r.Server==1&&r.Score[0]==0&&r.Winner<0,"alternate rematch opener");
  Vector3 p=new Vector3(0,2,-1),v=new Vector3(0,0,10);WallballFlight.Step(ref p,ref v,.1f,12,.45f,.9f,.88f,8,20,out bool bounce);check(v.z<0&&!bounce,"wall rebound prediction");p=new Vector3(0,.46f,-5);v=new Vector3(0,-5,-2);WallballFlight.Step(ref p,ref v,.04f,12,.45f,.9f,.88f,8,20,out bounce);check(bounce&&v.y>0,"floor prediction");Debug.Log("WB_RULE_FIXTURES_PASS count="+n);}
 static void Point(WallballRules r,int winner){if(r.Phase==WallballPhase.Point){r.Tick(2);r.Tick(2);}if(r.Server==winner){r.Strike(r.Server);r.Wall(true);r.Floor();r.Floor();}else r.Fault(r.Server,"SERVE TIMEOUT");}
}
}
